From Coq Require Import List String.
From Buri Require Import Wire Native.
Import ListNotations Native.Native.
Open Scope string_scope.
Definition eq1_theory_text_0 : string := "".
Definition eq1_theory_text_1 : string := "".
Definition eq1_theory_text_2 : string := "".
Definition eq1_theory_text_3 : string := "".
Definition eq1_theory_text_4 : string := "".
Definition eq1_theory_text_5 : string := "".
Definition eq1_theory_text_6 : string := "".
Definition eq1_theory_text_7 : string := "".
Definition eq1_theory_text : string := (eq1_theory_text_0 ++ eq1_theory_text_1 ++ eq1_theory_text_2 ++ eq1_theory_text_3 ++ eq1_theory_text_4 ++ eq1_theory_text_5 ++ eq1_theory_text_6 ++ eq1_theory_text_7)%string.
Definition eq1_theory_nodes :=
 match Wire.decode_text eq1_theory_text with
 | Some (Wire.Cons (Wire.Atom false "buri-constructor-native-1") (Wire.Cons tagged Wire.Nil)) =>
   match untag 500 tagged with Some root => elements root | _ => None end
 | _ => None end.
Definition eq1_theory_decode := match eq1_theory_nodes with
 | Some xs => definitions 500 (firstn 4 (skipn 0 xs)) | None => None end.
Definition eq1_theory_program := Eval vm_compute in
 match eq1_theory_decode with Some ds => ds | None => [] end.
Theorem eq1_theory_exact : eq1_theory_decode = Some eq1_theory_program.
Proof. vm_compute. reflexivity. Qed.
Theorem eq1_theory_names : map fst eq1_theory_program = ["kl:buri.signature";"kl:buri.constructors";"kl:buri.rules";"kl:buri.theory"].
Proof. vm_compute. reflexivity. Qed.
Theorem eq1_theory_complete : match eq1_theory_nodes with
 | Some xs => List.length xs = 4 | None => False end.
Proof. vm_compute; reflexivity. Qed.
Global Opaque eq1_theory_text_0 eq1_theory_text_1 eq1_theory_text_2 eq1_theory_text_3 eq1_theory_text_4 eq1_theory_text_5 eq1_theory_text_6 eq1_theory_text_7 eq1_theory_text eq1_theory_nodes eq1_theory_decode.
